        // Fault107. HTTP Violation: no-415-if-no-payload.
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 415 not defined for path '/PasswordReset/simple-mail/reset'.
        given().accept("*/*")
                .cookies(cookies_userB)
                .noContentType()
                .post("${baseUrlOfSut}/WebGoat/PasswordReset/simple-mail/reset?emailReset=iQ_PqOEgFo")
                .then()
                .statusCode(415)
                .assertThat()
                .contentType("application/json")
                .body("'status'", numberMatches(415))
                .body("'error'", containsString("Unsupported Media Type"))
                .body("'path'", containsString("/WebGoat/PasswordReset/simple-mail/reset"))
    }
    
    
